import{e as l,W as i,j as r,m as d}from"./chunks/framework.4B01ihDa.js";const p=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/introduction.md","filePath":"zh-CN/guide/introduction.md","lastUpdated":null}'),a={name:"zh-CN/guide/introduction.md"};function e(o,t,n,s,u,h){return i(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><p>JustForFun-UI 是一个轻量级、高性能的 Vue 3 组件库，专为现代 Web 应用设计。</p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>在现代 Web 开发中，UI 组件库在提高开发效率方面扮演着重要角色。然而，许多现有的组件库存在以下痛点：</p><ul><li><strong>体积庞大</strong>：传统组件库通常包含许多不必要的功能，导致包体积过大</li><li><strong>API 复杂</strong>：过于复杂的 API 增加了学习成本</li><li><strong>缺乏灵活性</strong>：难以自定义样式和行为</li><li><strong>性能问题</strong>：一些库在复杂场景下存在性能瓶颈</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>JustForFun-UI 旨在通过以下方式解决这些问题：</p><ul><li>提供轻量级、高性能的 Vue 3 组件库</li><li>简单直观的 API 设计</li><li>高度可定制的灵活性</li><li>优秀的性能和开发者体验</li></ul><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><ul><li><strong>Vue 3</strong> 配合 Composition API</li><li><strong>TypeScript</strong> 提供类型安全</li><li><strong>Vite</strong> 实现快速开发和构建</li><li><strong>SCSS</strong> 配合 CSS 变量进行样式管理</li><li><strong>Vitest</strong> 用于单元测试</li></ul><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h2><ol><li><p><strong>轻量级架构</strong></p><ul><li>支持 Tree-shaking 按需导入</li><li>最小化依赖</li><li>小包体积（gzip 后小于 20KB）</li></ul></li><li><p><strong>类型安全</strong></p><ul><li>完整的 TypeScript 支持</li><li>全面的类型定义</li><li>智能 IDE 自动补全</li></ul></li><li><p><strong>可定制主题</strong></p><ul><li>基于 CSS 变量的主题系统</li><li>内置明暗模式支持</li><li>轻松的品牌定制</li></ul></li><li><p><strong>无障碍访问</strong></p><ul><li>符合 WCAG 2.1 标准</li><li>支持键盘导航</li><li>兼容屏幕阅读器</li></ul></li><li><p><strong>性能优化</strong></p><ul><li>大数据列表虚拟滚动</li><li>支持懒加载</li><li>高效的重新渲染策略</li></ul></li></ol><h2 id="成果" tabindex="-1">成果 <a class="header-anchor" href="#成果" aria-label="Permalink to &quot;成果&quot;">​</a></h2><p>JustForFun-UI 已取得以下成果：</p><ul><li><strong>10+ 生产就绪组件</strong>：Button、Input、Modal、DatePicker 等</li><li><strong>85% 测试覆盖率</strong>：全面的单元测试确保可靠性</li><li><strong>35% 开发效率提升</strong>：已在 3+ 内部项目中使用</li><li><strong>活跃的社区</strong>：定期更新和维护</li></ul><h2 id="对比" tabindex="-1">对比 <a class="header-anchor" href="#对比" aria-label="Permalink to &quot;对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>JustForFun-UI</th><th>Element Plus</th><th>Ant Design Vue</th></tr></thead><tbody><tr><td>包体积</td><td>~20KB</td><td>~150KB</td><td>~200KB</td></tr><tr><td>Vue 3 支持</td><td>原生</td><td>原生</td><td>原生</td></tr><tr><td>TypeScript</td><td>完整</td><td>完整</td><td>完整</td></tr><tr><td>按需导入</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>暗黑模式</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>可定制性</td><td>高</td><td>中</td><td>中</td></tr></tbody></table><h2 id="浏览器兼容性" tabindex="-1">浏览器兼容性 <a class="header-anchor" href="#浏览器兼容性" aria-label="Permalink to &quot;浏览器兼容性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>浏览器</th><th>版本</th></tr></thead><tbody><tr><td>Chrome</td><td>&gt;= 90</td></tr><tr><td>Firefox</td><td>&gt;= 88</td></tr><tr><td>Safari</td><td>&gt;= 14</td></tr><tr><td>Edge</td><td>&gt;= 90</td></tr><tr><td>IE</td><td>❌ 不支持</td></tr></tbody></table><blockquote><p>注意：由于 Vue 3 的最低浏览器要求，不支持 Internet Explorer。</p></blockquote>',20)])])}const c=l(a,[["render",e]]);export{p as __pageData,c as default};
